PureJsonDTO dto = new PureJsonDTO();
dto.Name = 'Cabin';
dto.Count = 3;
dto.Tags = new List<String>{'spruce', 'hemlock'};
String compact = JSON.serialize(dto);
System.assert(compact.contains('"Name":"Cabin"'));
System.assert(compact.contains('"Count":3'));
System.assert(compact.contains('"Tags":["spruce","hemlock"]'));
String pretty = JSON.serializePretty(dto);
System.assert(pretty.contains('"Name" : "Cabin"'));
System.assert(pretty.contains('"Count" : 3'));
System.assert(pretty.contains('"Tags" : [ "spruce", "hemlock" ]'));
PureJsonDTO decoded = JSON.deserialize(compact, PureJsonDTO.class);
System.assertEquals('Cabin', decoded.Name);
System.assertEquals(3, decoded.Count);
System.assertEquals(2, decoded.Tags.size());
System.assertEquals('hemlock', decoded.Tags[1]);
PureJsonDTO strictDecoded = JSON.deserializeStrict('{"Name":"Lake","Count":4,"Tags":["clear","cold"]}', PureJsonDTO.class);
System.assertEquals('Lake', strictDecoded.Name);
System.assertEquals(4, strictDecoded.Count);
System.assertEquals('cold', strictDecoded.Tags[1]);
Boolean strictRejected = false;
try {
  PureJsonDTO bad = JSON.deserializeStrict('{"Name":"Overfull","Count":1,"Tags":[],"Extra":"no"}', PureJsonDTO.class);
} catch (JSONException e) {
  strictRejected = e.getMessage().contains('unknown field "Extra"');
}
System.assert(strictRejected);
Object root = JSON.deserializeUntyped('{"nested":{"label":"bank","values":["spruce","stone"],"meta":{"depth":2}}}');
Object nested = root.get('nested');
System.assertEquals('bank', nested.get('label'));
Object values = nested.get('values');
System.assertEquals('stone', values.get(1));
Object meta = nested.get('meta');
System.assertEquals(2, meta.get('depth'));

